select case when s.rating >= 4.2 then 'high' when s.rating >= 1.6 then 'mid' else 'low' end as rating_bucket, count(distinct p.price) as unique_suppliers, round(avg(p.stock_qty), 2) as avg_stock_qty from products p inner join suppliers s on p.supplier_id = s.id group by case when s.rating >= 4.2 then 'high' when s.rating >= 1.6 then 'mid' else 'low' end having round(avg(p.stock_qty), 2) > 68
